INSERT INTO term (id, entry_id, lang, text) VALUES (445, 149, 'en', 'Please move away from the area.');
INSERT INTO term (id, entry_id, lang, text) VALUES (446, 149, 'tr', 'Lütfen alanı boşaltın. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (447, 149, 'es', 'Por favor, necesito que todos se alejen de la escena /se alejen de aquí');
INSERT INTO term (id, entry_id, lang, text) VALUES (448, 150, 'en', 'Please, don’t touch or try to move the injured');
INSERT INTO term (id, entry_id, lang, text) VALUES (449, 150, 'tr', 'Lütfen yaralıya dokunmayın ve yaralıyı hareket ettirmeye çalışmayın');
INSERT INTO term (id, entry_id, lang, text) VALUES (450, 150, 'es', 'Por favor, no toquen ni intenten mover al herido');
INSERT INTO term (id, entry_id, lang, text) VALUES (451, 151, 'en', 'I need you to call the police / fire department.');
INSERT INTO term (id, entry_id, lang, text) VALUES (452, 151, 'tr', 'Polisi / İtfaiyeyi aramanız lazım.');
INSERT INTO term (id, entry_id, lang, text) VALUES (453, 151, 'es', 'Necesito que llame a la Policía / Bomberos');
INSERT INTO term (id, entry_id, lang, text) VALUES (454, 152, 'en', 'Call 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (455, 152, 'tr', '112''yi arayın');
INSERT INTO term (id, entry_id, lang, text) VALUES (456, 152, 'es', 'Llame al 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (457, 153, 'en', 'Stay on the line until help arrives');
INSERT INTO term (id, entry_id, lang, text) VALUES (458, 153, 'tr', 'Yardım gelene kadar hatta kalın');
INSERT INTO term (id, entry_id, lang, text) VALUES (459, 153, 'es', 'Manténgase en la linea hasta que la ayuda llegue');
INSERT INTO term (id, entry_id, lang, text) VALUES (460, 154, 'en', 'What happened?');
INSERT INTO term (id, entry_id, lang, text) VALUES (461, 154, 'tr', 'Ne oldu?');
INSERT INTO term (id, entry_id, lang, text) VALUES (462, 154, 'es', '¿Qué sucedió? / ¿Qué ha pasado?');
INSERT INTO term (id, entry_id, lang, text) VALUES (463, 155, 'en', 'How long ago did it happen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (464, 155, 'tr', 'Ne kadar zaman oldu / geçti?');
INSERT INTO term (id, entry_id, lang, text) VALUES (465, 155, 'es', '¿Hace cuánto tiempo pasó?');
INSERT INTO term (id, entry_id, lang, text) VALUES (466, 156, 'en', 'How many people are there?');
INSERT INTO term (id, entry_id, lang, text) VALUES (467, 156, 'tr', 'Kaç kişi var?');
INSERT INTO term (id, entry_id, lang, text) VALUES (468, 156, 'es', '¿Cuántas personas son?');
INSERT INTO term (id, entry_id, lang, text) VALUES (469, 157, 'en', 'Were you able to see if anyone was injured?');
INSERT INTO term (id, entry_id, lang, text) VALUES (470, 157, 'tr', 'Yaralanan biri var mıydı, görebildiniz mi?');
INSERT INTO term (id, entry_id, lang, text) VALUES (471, 157, 'es', '¿Pudo ver si hay alguien herido?');
INSERT INTO term (id, entry_id, lang, text) VALUES (472, 158, 'en', 'Where are the injured people?');
INSERT INTO term (id, entry_id, lang, text) VALUES (473, 158, 'tr', 'Yaralılar nerede?');
INSERT INTO term (id, entry_id, lang, text) VALUES (474, 158, 'es', '¿Dónde están los heridos?');
INSERT INTO term (id, entry_id, lang, text) VALUES (475, 159, 'en', 'Are they trapped?');
INSERT INTO term (id, entry_id, lang, text) VALUES (476, 159, 'tr', 'Mahsur mu kaldılar?');
INSERT INTO term (id, entry_id, lang, text) VALUES (477, 159, 'es', '¿Están atrapados?');
INSERT INTO term (id, entry_id, lang, text) VALUES (478, 160, 'en', 'Are they conscious/responsive?');
INSERT INTO term (id, entry_id, lang, text) VALUES (479, 160, 'tr', 'Bilinçleri yerinde mi?');
INSERT INTO term (id, entry_id, lang, text) VALUES (480, 160, 'es', '¿Están conscientes?');
INSERT INTO term (id, entry_id, lang, text) VALUES (481, 161, 'en', 'How long have they been unconscious/unresponsive?');
INSERT INTO term (id, entry_id, lang, text) VALUES (482, 161, 'tr', 'Ne zamandır bilinçleri yok?');
INSERT INTO term (id, entry_id, lang, text) VALUES (483, 161, 'es', '¿Cuánto tiempo hace que están inconscientes?');
INSERT INTO term (id, entry_id, lang, text) VALUES (484, 162, 'en', 'Were you able to talk with them?');
INSERT INTO term (id, entry_id, lang, text) VALUES (485, 162, 'tr', 'Onlarla konuşabildiniz mi?');
INSERT INTO term (id, entry_id, lang, text) VALUES (486, 162, 'es', '¿Ha logrado hablar con ellos?');
INSERT INTO term (id, entry_id, lang, text) VALUES (487, 163, 'en', 'Where is the accident?');
INSERT INTO term (id, entry_id, lang, text) VALUES (488, 163, 'tr', 'Kaza yeri nerede?');
INSERT INTO term (id, entry_id, lang, text) VALUES (489, 163, 'es', '¿Dónde ha ocurrido el accidente?');
INSERT INTO term (id, entry_id, lang, text) VALUES (490, 164, 'en', 'Where does it hurt?');
INSERT INTO term (id, entry_id, lang, text) VALUES (491, 164, 'tr', 'Neresi acıyor?');
INSERT INTO term (id, entry_id, lang, text) VALUES (492, 164, 'es', '¿Dónde le duele?');
INSERT INTO term (id, entry_id, lang, text) VALUES (493, 165, 'en', 'Blink once for yes and twice for no');
INSERT INTO term (id, entry_id, lang, text) VALUES (494, 165, 'tr', 'Evet demek için bir sefer, hayır için iki sefer gözünü kırp.');
INSERT INTO term (id, entry_id, lang, text) VALUES (495, 165, 'es', 'Pestañee una vez para decir si o dos para decir no');
INSERT INTO term (id, entry_id, lang, text) VALUES (496, 166, 'en', 'Can you hear me?');
INSERT INTO term (id, entry_id, lang, text) VALUES (497, 166, 'tr', 'Beni duyabiliyor musun?');
INSERT INTO term (id, entry_id, lang, text) VALUES (498, 166, 'es', '¿Puede oírme?');
