INSERT INTO term (id, entry_id, lang, text) VALUES (5467, 149, 'zh-Hant', '請大家遠離現場！');
INSERT INTO term (id, entry_id, lang, text) VALUES (5468, 149, 'bg', 'Моля, всеки да се отдалечи от района.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5469, 149, 'ko', '모두 현장에서 떨어져 주시기 바랍니다');
INSERT INTO term (id, entry_id, lang, text) VALUES (5470, 149, 'fa', 'لطفا، هرکس منطقه ارو ترک کنه');
INSERT INTO term (id, entry_id, lang, text) VALUES (5471, 149, 'hi', 'कृपया, आप सभी इस जगह से दूर रहें');
INSERT INTO term (id, entry_id, lang, text) VALUES (5472, 149, 'pt', 'Por favor, preciso que se mantenham todos afastados do local');
INSERT INTO term (id, entry_id, lang, text) VALUES (5473, 149, 'sv', 'Ta dig bort från området.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5474, 149, 'ro', 'Vă rugăm ca toată lumea să iasă în afara zonei ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5475, 149, 'mk', 'Ве молам, не приближувајте се до местото на настанот');
INSERT INTO term (id, entry_id, lang, text) VALUES (5476, 149, 'hu', 'Kérem, hagyja el a területet!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5477, 149, 'fi', 'Poistukaa alueelta');
INSERT INTO term (id, entry_id, lang, text) VALUES (5478, 149, 'cs', 'Prosím opusťte oblast.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5479, 149, 'pl', 'Proszę opuścić teren');
INSERT INTO term (id, entry_id, lang, text) VALUES (5480, 150, 'de', 'Berühren Sie die verletzte Person nicht und versuchen Sie nicht, sie zu bewegen.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5481, 150, 'ru', 'Пожалуйста, не трогайте и не перемещайте пострадавшего.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5482, 150, 'fr', 'S''il vous plaît, ne touchez pas le blessé et ne tentez pas de le faire bouger ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5483, 150, 'kmr', 'Ji kerema xwe destê xwe nedin kesê birîndar û nehêlin bi lebite');
INSERT INTO term (id, entry_id, lang, text) VALUES (5484, 150, 'zza', 'dest xu yarali mede');
INSERT INTO term (id, entry_id, lang, text) VALUES (5485, 150, 'ar', 'يُرجى عدم لمس المُصاب أو محاولة تحريكه');
INSERT INTO term (id, entry_id, lang, text) VALUES (5486, 150, 'el', 'Παρακαλώ, μην αγγίξετε ή προσπαθήσετε να μετακινήσετε τον τραυματία.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5487, 150, 'ja', '負傷者に触れたり、動かそうとしたりしないでください');
INSERT INTO term (id, entry_id, lang, text) VALUES (5488, 150, 'he', 'בבקשה לא לגעת בפצועים ולא לנסות להזיז אותם');
INSERT INTO term (id, entry_id, lang, text) VALUES (5489, 150, 'it', 'Non toccatre né cercare di muovere il ferito');
INSERT INTO term (id, entry_id, lang, text) VALUES (5490, 150, 'hy', 'Խնդրում ենք չդիպչել վիրավորին և չփորձել շարժել նրան։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5491, 150, 'nl', 'Gelieve de gewonden niet aan te raken, en probeer niet hen te verplaatsen. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5492, 150, 'zh-Hans', '请不要碰触/触摸或试图移动伤者。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5493, 150, 'zh-Hant', '請勿觸碰或試圖移動傷者');
INSERT INTO term (id, entry_id, lang, text) VALUES (5494, 150, 'bg', 'Моля, не докосвайте и не се опитвайте да мърдате ранените.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5495, 150, 'ko', '부상자들을 만지거나 옮기지 마십시오');
INSERT INTO term (id, entry_id, lang, text) VALUES (5496, 150, 'fa', 'لطفا به زخمی ها دست نزنید و تکانشان ندهید ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5497, 150, 'hi', 'कृपया, घायलों को छूने या हिलाने की कोशिश न करें');
INSERT INTO term (id, entry_id, lang, text) VALUES (5498, 150, 'pt', 'Por favor, não toquem ou tentem mover os feridos');
INSERT INTO term (id, entry_id, lang, text) VALUES (5499, 150, 'sv', 'Rör inte och försök inte att flytta den skadade personen');
INSERT INTO term (id, entry_id, lang, text) VALUES (5500, 150, 'ro', 'Vă rugăm să nu atingeți și să nu încercați să mutați persoana rănită ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5501, 150, 'mk', 'Ве молам, немојте да го допирате или поместувате повредениот');
INSERT INTO term (id, entry_id, lang, text) VALUES (5502, 150, 'hu', 'Kérem, ne érjen a sebesülthöz, és ne mozdítsa el!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5503, 150, 'fi', 'Älä koske tai yritä liikuttaa loukkaantuneita.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5504, 150, 'cs', 'Prosím nedotýkejte se nebo se nesnažte pohnout zraněným. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5505, 150, 'pl', 'Proszę nic nie dotykać ani nic nie ruszać');
INSERT INTO term (id, entry_id, lang, text) VALUES (5506, 151, 'de', 'Sie müssen die Polizei/Feuerwehr anrufen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5507, 151, 'ru', 'Вам нужно вызвать полицию/пожарных.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5508, 151, 'fr', 'Il faut que vous appeliez la police / les pompiers ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5509, 151, 'kmr', 'Divê hûn gazî polîs/agirkuje bikin/divê hûn telefoni polîs/agirkuje bikin');
INSERT INTO term (id, entry_id, lang, text) VALUES (5510, 151, 'zza', 'Polisra/itfaiyera telefon bikerin');
INSERT INTO term (id, entry_id, lang, text) VALUES (5511, 151, 'ar', 'أريدك أن تتصل بالشرطة / رجال الإطفاء');
INSERT INTO term (id, entry_id, lang, text) VALUES (5512, 151, 'el', 'Πρέπει να καλέσετε την αστυνομία/την πυροσβεστική');
INSERT INTO term (id, entry_id, lang, text) VALUES (5513, 151, 'ja', '警察/消防士に連絡してください');
INSERT INTO term (id, entry_id, lang, text) VALUES (5514, 151, 'he', 'בבקשה להתקשר למשטרה / לכיבוי');
INSERT INTO term (id, entry_id, lang, text) VALUES (5515, 151, 'it', 'Chiama la polizia / i vigili del fuoco');
INSERT INTO term (id, entry_id, lang, text) VALUES (5516, 151, 'hy', 'Պետք է զանգահարեք ոստիկանություն / հրշեջ ծառայություն։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5517, 151, 'nl', 'Bel de poltie / brandweer. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5518, 151, 'zh-Hans', '请你给警察/消防员打电话。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5519, 151, 'zh-Hant', '請打給警察/消防局');
INSERT INTO term (id, entry_id, lang, text) VALUES (5520, 151, 'bg', 'Трябва да се свържите с полицията / пожарната.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5521, 151, 'ko', '경찰/소방서에 전화하세요 ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5522, 151, 'fa', 'با پلیس یا آتش نشانی تماس بگیرید ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5523, 151, 'hi', 'कृपया पुलिस/फायरब्रिगेड को कॉल करें');
INSERT INTO term (id, entry_id, lang, text) VALUES (5524, 151, 'pt', 'Preciso que ligue para a polícia/para os bombeiros');
INSERT INTO term (id, entry_id, lang, text) VALUES (5525, 151, 'sv', 'Ring polisen / brandkåren.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5526, 151, 'ro', 'Trebuie să sunați la poliție / pompieri');
INSERT INTO term (id, entry_id, lang, text) VALUES (5527, 151, 'mk', 'Викнете полиција / противпожарна служба');
INSERT INTO term (id, entry_id, lang, text) VALUES (5528, 151, 'hu', 'Hívja a rendőrséget / tűzoltókat!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5529, 151, 'fi', 'Soita poliisi / palokunta');
INSERT INTO term (id, entry_id, lang, text) VALUES (5530, 151, 'cs', 'Potřebuji abyste zavolal policii / hasiče.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5531, 151, 'pl', 'Potrzebuje abyś zadzwonił na policje / straż pożarną / pogotowie');
INSERT INTO term (id, entry_id, lang, text) VALUES (5532, 152, 'de', 'Rufen sie die nummer 112 an?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5533, 152, 'ru', 'Позвоните по номеру 112.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5534, 152, 'fr', 'Appelez le 112 ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5535, 152, 'kmr', 'Li 112 bi gerin/Telefoni 112 bike');
INSERT INTO term (id, entry_id, lang, text) VALUES (5536, 152, 'zza', '112ra telefon bikerin');
INSERT INTO term (id, entry_id, lang, text) VALUES (5537, 152, 'ar', 'اتصل بـ 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5538, 152, 'el', 'Καλέστε το 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5539, 152, 'ja', '112番通報してください');
INSERT INTO term (id, entry_id, lang, text) VALUES (5540, 152, 'he', 'בבקשה להתקשר לשירותי החירום');
INSERT INTO term (id, entry_id, lang, text) VALUES (5541, 152, 'it', 'Chiama il 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5542, 152, 'hy', 'Զանգահարել 122');
INSERT INTO term (id, entry_id, lang, text) VALUES (5543, 152, 'nl', 'Bel 112. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5544, 152, 'zh-Hans', '打112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5545, 152, 'zh-Hant', '打給112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5546, 152, 'bg', 'Звънете на 112.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5547, 152, 'ko', '112에 전화하세요 ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5548, 152, 'fa', 'به 112 زنگ بزنید ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5549, 152, 'hi', '112 पर कॉल करें');
INSERT INTO term (id, entry_id, lang, text) VALUES (5550, 152, 'pt', 'Ligue para o 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5551, 152, 'sv', 'Ring 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5552, 152, 'ro', 'Sunați la 112 (unu-unu-doi)');
INSERT INTO term (id, entry_id, lang, text) VALUES (5553, 152, 'mk', 'Повикајте 122');
INSERT INTO term (id, entry_id, lang, text) VALUES (5554, 152, 'hu', 'Hívja a 112-t!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5555, 152, 'fi', 'Soita 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5556, 152, 'cs', 'Zavolejte 112.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5557, 152, 'pl', 'Zadzwoń na 112');
INSERT INTO term (id, entry_id, lang, text) VALUES (5558, 153, 'de', 'Bleiben sie an der Leitung bis jemand Hilfe ankommt? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5559, 153, 'ru', 'Оставайтесь на линии до прибытия помощи.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5560, 153, 'fr', 'Restez en ligne jusqu’à ce que les secours arrivent ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5561, 153, 'kmr', 'Heta ku alîkarî were li ser xetê bimînin');
INSERT INTO term (id, entry_id, lang, text) VALUES (5562, 153, 'zza', 'xeta ke yardım  ame windere');
INSERT INTO term (id, entry_id, lang, text) VALUES (5563, 153, 'ar', 'ابقَ على الخط حتى وصول المساعدة');
INSERT INTO term (id, entry_id, lang, text) VALUES (5564, 153, 'el', 'Μείνετε στη γραμμή μέχρι να έρθει βοήθεια');
INSERT INTO term (id, entry_id, lang, text) VALUES (5565, 153, 'ja', '救助が到着するまで電話を切らないでください');
INSERT INTO term (id, entry_id, lang, text) VALUES (5566, 153, 'he', 'בבקשה להישאר על הקו עד שתגיע עזרה');
INSERT INTO term (id, entry_id, lang, text) VALUES (5567, 153, 'it', 'Resta in linea fino all''arrivo dei soccorsi');
INSERT INTO term (id, entry_id, lang, text) VALUES (5568, 153, 'hy', 'Մնացեք գծում, մինչև օգնությունը կհասնի։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5569, 153, 'nl', 'Blijf aan de lijn tot er hulp arriveert. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5570, 153, 'zh-Hans', '直到救援人员到达保持通话。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5571, 153, 'zh-Hant', '在救援人員抵達前，請勿掛斷電話');
INSERT INTO term (id, entry_id, lang, text) VALUES (5572, 153, 'bg', 'Останете на линия докато помощта пристигне.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5573, 153, 'ko', '도와줄 사람이 올 때까지 끊지 마세요 ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5574, 153, 'fa', 'تا زمانی که کمک‌رسانی برسد پشت خط بمونید ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5575, 153, 'hi', 'मदद आने तक कॉल पर बने रहें');
INSERT INTO term (id, entry_id, lang, text) VALUES (5576, 153, 'pt', 'Mantenha-se em linha até que a ajuda chegue');
INSERT INTO term (id, entry_id, lang, text) VALUES (5577, 153, 'sv', 'Fortsätt samtalet tills hjälpen har kommit fram');
INSERT INTO term (id, entry_id, lang, text) VALUES (5578, 153, 'ro', 'Rămâneți pe linie până când sosesc ajutoarele');
INSERT INTO term (id, entry_id, lang, text) VALUES (5579, 153, 'mk', 'Останете на линија додека да дојде помош');
INSERT INTO term (id, entry_id, lang, text) VALUES (5580, 153, 'hu', 'Maradjon vonalban, amíg megérkezik a segítség!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5581, 153, 'fi', 'Pysy linjalla, kunnes apu saapuu');
INSERT INTO term (id, entry_id, lang, text) VALUES (5582, 153, 'pl', 'Zostań na lini do przybycia pomocy');
INSERT INTO term (id, entry_id, lang, text) VALUES (5583, 154, 'de', 'Was ist passiert?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5584, 154, 'ru', 'Что случилось?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5585, 154, 'fr', 'Qu''est-ce qu''il s''est passé ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5586, 154, 'kmr', 'Çi bû?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5587, 154, 'zza', 'se bi');
INSERT INTO term (id, entry_id, lang, text) VALUES (5588, 154, 'ar', 'ماذا حصل؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5589, 154, 'el', 'Τι συνέβη;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5590, 154, 'ja', 'どうしましたか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5591, 154, 'he', 'מה קרה?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5592, 154, 'it', 'Che cosa è successo?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5593, 154, 'hy', 'Ի՞նչ է պատահել։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5594, 154, 'nl', 'Wat is er gebeurd?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5595, 154, 'zh-Hans', '发生了什么？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5596, 154, 'zh-Hant', '發生什麼事了？ / 怎麼了？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5597, 154, 'bg', 'Какво стана?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5598, 154, 'ko', '무슨 일이 있었습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5599, 154, 'fa', 'چه اتفاقی افتاده است؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5600, 154, 'hi', 'क्या हुआ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5601, 154, 'pt', 'O que aconteceu?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5602, 154, 'sv', 'Vad hände?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5603, 154, 'ro', 'Ce s-a întâmplat?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5604, 154, 'mk', 'Што се случи?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5605, 154, 'hu', 'Mi történt?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5606, 154, 'fi', 'Mitä tapahtui?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5607, 154, 'pl', 'Co się stało?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5608, 155, 'de', 'Wieviel Zeit ist vergangen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5609, 155, 'ru', 'Сколько времени прошло?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5610, 155, 'fr', 'Ça fait combien de temps que cela s’est produit ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5611, 155, 'kmr', 'Çend dem derbas bûye?/Çiqas wext derbas bû?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5612, 155, 'zza', 'çi vaxt(vağt) bi');
INSERT INTO term (id, entry_id, lang, text) VALUES (5613, 155, 'ar', 'منذ متى حصل ذلك؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5614, 155, 'el', 'Πριν πόση ώρα συνέβη;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5615, 155, 'ja', 'これは、どれくらい前におきたことですか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5616, 155, 'he', 'לפני כמה זמן זה קרה?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5617, 155, 'it', 'Quando è successo?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5618, 155, 'hy', 'Որքա՞ն ժամանակ է անցել։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5619, 155, 'nl', 'Hoeveel tijd is er verstreken?  Hoe lang geleden is het gebeurd?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5620, 155, 'zh-Hans', '。。发生已经多长时间了？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5621, 155, 'zh-Hant', '…是多久以前發生的？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5622, 155, 'bg', 'Колко време мина?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5623, 155, 'ko', '그 일이 언제 일어났습니까?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5624, 155, 'fa', 'چقدر زمان گذشته است؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5625, 155, 'hi', 'यह कितनी देर पहले हुआ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5626, 155, 'pt', 'Há quanto tempo aconteceu?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5627, 155, 'sv', 'Hur länge sen hände det?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5628, 155, 'ro', 'Cât timp a trecut?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5629, 155, 'mk', 'Пред колку време се случи?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5630, 155, 'hu', 'Mennyi ideje történt?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5631, 155, 'fi', 'Milloin se tapahtui?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5632, 155, 'pl', 'Jak dawno temu to się stało?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5633, 156, 'de', 'Wie viele Personen sind dort?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5634, 156, 'ru', 'Сколько человек?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5635, 156, 'fr', 'Combien de personnes y a-t-il ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5636, 156, 'kmr', 'Çend kes li wir bûn?/Çend kes hebûn?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5637, 156, 'zza', 'çan teney esto');
INSERT INTO term (id, entry_id, lang, text) VALUES (5638, 156, 'ar', 'كم شخص يوجد هناك؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5639, 156, 'el', 'Πόσα άτομα υπάρχουν;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5640, 156, 'ja', '何人いますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5641, 156, 'he', 'כמה אנשים יש שם?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5642, 156, 'it', 'Quante persone ci sono?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5643, 156, 'hy', 'Քանի՞ հոգի կա։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5644, 156, 'nl', 'Hoeveel mensen zijn er aanwezig?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5645, 156, 'zh-Hans', '有多少人？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5646, 156, 'zh-Hant', '那裡有多少人？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5647, 156, 'bg', 'Колко души има?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5648, 156, 'ko', '사람이 얼마나 있습니까?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5649, 156, 'fa', 'چند نفر در اونجا هست؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5650, 156, 'hi', 'कितने लोग हैं वहाँ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5651, 156, 'pt', 'Quantas pessoas estão aí?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5652, 156, 'sv', 'Hur många personer är det där?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5653, 156, 'ro', 'Câți oameni sunt acolo?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5654, 156, 'mk', 'Колку луѓе има таму?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5655, 156, 'hu', 'Hány ember van ott?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5656, 156, 'fi', 'Kuinka monta ihmistä siellä on?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5657, 156, 'pl', 'Jak dużo jest tu osób?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5658, 157, 'de', 'Sind Verletzte Vorort? Sehen sie Verletzte?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5659, 157, 'ru', 'Вы видели, были ли пострадавшие?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5660, 157, 'fr', 'Avez-vous pu voir si quelqu’un a été blessé ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5661, 157, 'kmr', 'Kesekî ku birîndar bû hebû,we dît?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5662, 157, 'zza', 'keso dirvetin esto');
INSERT INTO term (id, entry_id, lang, text) VALUES (5663, 157, 'ar', 'هل عرفت ما إذا كان هناك أي شخص مُصاب؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5664, 157, 'el', 'Είδατε εάν υπάρχουν τραυματίες;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5665, 157, 'ja', 'けが人がいないか確認できましたか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5666, 157, 'he', 'הצלחת לראות אם מישהו נפגע?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5667, 157, 'it', 'Siete riusciti a vedere se c''è qualche ferito?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5668, 157, 'hy', 'Կարողացա՞ք տեսնել՝ վիրավոր կա՞ր։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5669, 157, 'nl', 'Kon u vaststellen dat er iemand gewond raakte?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5670, 157, 'zh-Hans', '你能看看有没有人受伤？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5671, 157, 'zh-Hant', '您當時是否有看到其他人也受傷了？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5672, 157, 'bg', 'Има ли ранени, успяхте ли да видите?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5673, 157, 'ko', '부상자가 있는지 확인했습니까?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5674, 157, 'fa', 'آنجا کسی را زخمی مشاهده کردید؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5675, 157, 'hi', 'क्या किसी को चोट लगी है?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5676, 157, 'pt', 'Consegue ver se há feridos?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5677, 157, 'sv', 'Såg du om någon blev skadad?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5678, 157, 'ro', 'Ați putut vedea dacă cineva e rănit?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5679, 157, 'mk', 'Видовте ли дали има повредени? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5680, 157, 'hu', 'Látta, hogy van-e sérült?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5681, 157, 'fi', 'Näitkö oliko kukaan loukkaantunut?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5682, 158, 'de', 'Wo sind die Verletzten? wo befinden sich die Verletzten?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5683, 158, 'ru', 'Где пострадавшие?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5684, 158, 'fr', 'Où sont les blessés ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5685, 158, 'kmr', 'Birîndar li ku ne?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5686, 158, 'zza', 'dirvetin kotye');
INSERT INTO term (id, entry_id, lang, text) VALUES (5687, 158, 'ar', 'اين المُصاب؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5688, 158, 'el', 'Πού είναι οι τραυματίες;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5689, 158, 'ja', 'けが人はどこですか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5690, 158, 'he', 'איפה הפצועים?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5691, 158, 'it', 'Dove sono i feriti?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5692, 158, 'hy', 'Որտե՞ղ են վիրավորները։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5693, 158, 'nl', 'Waar bevinden de gewonden zich?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5694, 158, 'zh-Hans', '受伤的人在哪里？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5695, 158, 'zh-Hant', '傷者人在哪裡？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5696, 158, 'bg', 'Къде са ранените?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5697, 158, 'ko', '부상자들이 어디에 있습니까?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5698, 158, 'fa', 'زخمی ها کجا هستند؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5699, 158, 'hi', 'घायल लोग कहाँ हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5700, 158, 'pt', 'Onde estão as pessoas feridas?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5701, 158, 'sv', 'Var är de skadade personerna?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5702, 158, 'ro', 'Unde sunt răniții?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5703, 158, 'mk', 'Каде се повредените (луѓе)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5704, 158, 'hu', 'Hol vannak a sebesültek?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5705, 158, 'fi', 'Oliko siellä loukkaantuneita?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5706, 158, 'pl', 'Gdzie są ranni ludzie?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5707, 159, 'de', 'Ist Jemand unter den Trümmern? Ist Jemand verschüttet?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5708, 159, 'ru', 'Они застряли?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5709, 159, 'fr', 'Sont-ils piégés/coincés ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5710, 159, 'kmr', 'Ma ew asê mane?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5711, 159, 'zza', 'uza zorde ment');
INSERT INTO term (id, entry_id, lang, text) VALUES (5712, 159, 'ar', 'هل هم مُحاصَرون؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5713, 159, 'el', 'Είναι παγιδευμένοι;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5714, 159, 'ja', '閉じ込められている人はいますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5715, 159, 'he', 'הם לכודים?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5716, 159, 'it', 'Sono intrappolati?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5717, 159, 'hy', 'Փակի տա՞կ են։ / Խրված մնացա՞ծ են։ / Ծուղակի մե՞ջ են։ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5718, 159, 'nl', 'Zitten ze vast?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5719, 159, 'zh-Hans', '他们是否被困住了？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5720, 159, 'zh-Hant', '他們被困住了嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5721, 159, 'bg', 'Заседнали ли са?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5722, 159, 'ko', '갇혀있습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5723, 159, 'fa', 'آیا گیر کرده اند؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5724, 159, 'hi', 'क्या वे फँसे हुए हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5725, 159, 'pt', 'Estão presas?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5726, 159, 'sv', 'Är de instängda?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5727, 159, 'ro', 'Au rămas prinși?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5728, 159, 'mk', 'Заглавени ли се? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5729, 159, 'hu', 'Beszorultak?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5730, 159, 'fi', 'Ovatko he loukussa?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5731, 159, 'pl', 'Czy są uwięzieni?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5732, 160, 'de', 'Sind sie bei Bewusstsein?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5733, 160, 'ru', 'Они находятся в сознании?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5734, 160, 'fr', 'Sont-ils conscients ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5735, 160, 'kmr', 'Li hişin?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5736, 160, 'zza', 'şuhuro ho esto');
INSERT INTO term (id, entry_id, lang, text) VALUES (5737, 160, 'ar', 'هل هم واعون؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5738, 160, 'el', 'Έχουν τις αισθήσεις τους;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5739, 160, 'ja', '意識はありますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5740, 160, 'he', 'הם בהכרה?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5741, 160, 'it', 'Sono coscienti? Reagiscono?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5742, 160, 'hy', 'Գիտակցությունը տե՞ղն է։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5743, 160, 'nl', 'Zijn ze bij bewustzijn?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5744, 160, 'zh-Hans', '他们有意识吗？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5745, 160, 'zh-Hant', '他們還有意識/反應嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5746, 160, 'bg', 'В съзнание ли са?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5747, 160, 'ko', '의식 / 반응이 있습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5748, 160, 'fa', 'آیا هوشیار هستند؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5749, 160, 'hi', 'क्या वे होश में हैं/जवाब दे रहे हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5750, 160, 'pt', 'Estão conscientes/responsivas?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5751, 160, 'sv', 'Är de vid medvetande?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5752, 160, 'ro', 'Sunt conștienți?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5753, 160, 'mk', 'Свесни ли се?/ реагираат ли?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5754, 160, 'hu', 'Eszméletüknél vannak?/Reagálnak?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5755, 160, 'fi', 'Ovatko he tajuissaan?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5756, 160, 'pl', 'Czy są przytomni? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5757, 161, 'de', 'Seit wann sind sie bewusstlos?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5758, 161, 'ru', 'Как давно они без сознания?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5759, 161, 'fr', 'Depuis combien de temps sont-ils inconscients ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5760, 161, 'kmr', 'Ji kengî ve ne lihişin ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5761, 161, 'zza', 'çı wağto şuhuro ho çino');
INSERT INTO term (id, entry_id, lang, text) VALUES (5762, 161, 'ar', 'منذ متى وهم فاقدون للوعي؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5763, 161, 'el', 'Πόση ώρα δεν είχαν τις αισθήσεις τους;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5764, 161, 'ja', '意識を失ってどれくらいたちますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5765, 161, 'he', 'כמה זמן הם חסרי הכרה?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5766, 161, 'it', 'Da quanto tempo hanno perso coscienza?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5767, 161, 'hy', 'Որքա՞ն ժամանակ է՝ գիտակցություն չկա։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5768, 161, 'nl', 'Sinds wanneer zijn ze bewusteloos?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5769, 161, 'zh-Hans', '他们昏迷了多长时间？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5770, 161, 'zh-Hant', '他們失去意識/反應多久了？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5771, 161, 'bg', 'От колко време не са в съзнание?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5772, 161, 'ko', '의식 / 반응이 없은 지 얼마나 됐습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5773, 161, 'fa', 'چقدر زمان هست که هوشیار نیستند‌؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5774, 161, 'hi', 'वे कितने समय से बेहोश हैं/ जवाब नहीं दे रहे?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5775, 161, 'pt', 'Há quanto tempo estão inconscientes/irresponsíveis?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5776, 161, 'sv', 'Hur länge har de varit medvetslösa?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5777, 161, 'ro', 'De câtă vreme și-au pierdut cunoștința?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5778, 161, 'mk', 'Колку долго се во несвест / не реагираат?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5779, 161, 'hu', 'Mióta eszméletlenek?/Mióta nem reagálnak?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5780, 161, 'fi', 'Kauanko he ovat olleet tajuttomina?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5781, 161, 'pl', 'Jak długo są nieprzytomni?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5782, 162, 'de', 'Konntest Du mit ihnen sprechen? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5783, 162, 'ru', 'Вы смогли с ними поговорить?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5784, 162, 'fr', 'Etes-vous arrivés à leur parler ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5785, 162, 'kmr', 'We dikarî biaxivîn?/We karîbû xeber bidin?/We karîbû biaxivîn?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5786, 162, 'zza', 'sıma tey kesey kerd');
INSERT INTO term (id, entry_id, lang, text) VALUES (5787, 162, 'ar', 'هل استطعت التحدث معهم؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5788, 162, 'el', 'Μπορέσατε να τους μιλήσετε;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5789, 162, 'ja', '本人と話すことはできましたか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5790, 162, 'he', 'הצלחת לדבר איתם?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5791, 162, 'it', 'Sei riuscito/a a parlarci?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5792, 162, 'hy', 'Կարողացա՞ք խոսել նրանց հետ:');
INSERT INTO term (id, entry_id, lang, text) VALUES (5793, 162, 'nl', 'Kon u met hen spreken?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5794, 162, 'zh-Hans', '你能不能跟他们交流？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5795, 162, 'zh-Hant', '您是否能跟他們說話/溝通？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5796, 162, 'bg', 'Успяхте ли да говорите (с тях)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5797, 162, 'ko', '그들과 의사 소통을 할 수 있었습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5798, 162, 'fa', 'آیا توانستید با آنها صحبت کنید؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5799, 162, 'hi', 'क्या आपकी उनसे बात हुई?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5800, 162, 'pt', 'Conseguiu falar com elas?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5801, 162, 'sv', 'Kunde du prata med dem?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5802, 162, 'ro', 'Ați putut să vorbiți cu ei?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5803, 162, 'mk', 'Дали зборувавте со нив?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5804, 162, 'hu', 'Tudott beszélni velük?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5805, 162, 'fi', 'Pystyitkö puhumaan heidän kanssaan?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5806, 162, 'pl', 'Byłeś w stanie z nimi porozmawiać?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5807, 163, 'de', 'Wo ist der Unfall passiert?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5808, 163, 'ru', 'Где место происшествия?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5809, 163, 'fr', 'Où est le lieu de l''accident ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5810, 163, 'kmr', 'Cihê qezayê kudere?/cihê qezayê li ku ye?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5811, 163, 'zza', 'gaza vejiya, kotyo');
INSERT INTO term (id, entry_id, lang, text) VALUES (5812, 163, 'ar', 'أين مكان الحادث؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5813, 163, 'el', 'Πού συνέβη το ατύχημα;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5814, 163, 'ja', '事故現場はどこですか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5815, 163, 'he', 'איפה קרתה התאונה?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5816, 163, 'it', 'Dov''è l''incidente?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5817, 163, 'hy', 'Որտե՞ղ է վթարի վայրը։ / Որտե՞ղ է դեպքի վայրը։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5818, 163, 'nl', 'Waar vond het ongeval plaats?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5819, 163, 'zh-Hans', '事故现场在哪里？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5820, 163, 'zh-Hant', '事故現場在哪裡？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5821, 163, 'bg', 'Къде е мястото на инцидента?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5822, 163, 'ko', '사고 현장이 어디입니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5823, 163, 'fa', 'منطقه تصادف کجاست ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5824, 163, 'hi', 'दुर्घटना कहाँ हुई?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5825, 163, 'pt', 'Onde é o acidente?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5826, 163, 'sv', 'Var är olyckan?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5827, 163, 'ro', 'Unde este locul accidentului?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5828, 163, 'mk', 'Каде се случи несреќата? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5829, 163, 'hu', 'Hol történt a baleset?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5830, 163, 'fi', 'Missä onnettomuus on?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5831, 163, 'pl', 'Gdzie stał się wypadek?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5832, 164, 'de', 'Wo tut es weh?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5833, 164, 'ru', 'Где болит?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5834, 164, 'fr', 'Où cela fait-il mal? / ça fait mal où ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5835, 164, 'kmr', 'Kuder diêşe?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5836, 164, 'zza', 'kotye to dezeno');
INSERT INTO term (id, entry_id, lang, text) VALUES (5837, 164, 'ar', 'أين تتألّم؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5838, 164, 'el', 'Πού πονάτε;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5839, 164, 'ja', '痛い場所を教えて下さい。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5840, 164, 'he', 'זה כואב?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5841, 164, 'it', 'Dove ti fa male?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5842, 164, 'hy', 'Ի՞նչն է ցավում։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5843, 164, 'nl', 'Waar doet het pijn?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5844, 164, 'zh-Hans', '哪里不舒服？// 哪里有疼？ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5845, 164, 'zh-Hant', '您哪裡在痛？ / 您哪裡會痛？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5846, 164, 'bg', 'Къде (те) боли?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5847, 164, 'ko', '어디를 다쳤습니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5848, 164, 'fa', 'کدام قسمت بدنش درد میکند؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5849, 164, 'hi', 'कहाँ दर्द हो रहा है?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5850, 164, 'pt', 'Onde dói?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5851, 164, 'sv', 'Var gör det ont?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5852, 164, 'ro', 'Unde doare?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5853, 164, 'mk', 'Каде (те) боли?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5854, 164, 'hu', 'Hol fáj?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5855, 164, 'fi', 'Mihin sattuu?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5856, 164, 'pl', 'Gdzie boli?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5857, 165, 'de', 'Blinzel für "Ja" ein Mal und für "Nein" zwei Mal.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5858, 165, 'ru', 'Моргните один раз, если "ДА", и два раза, если "НЕТ".');
INSERT INTO term (id, entry_id, lang, text) VALUES (5859, 165, 'fr', 'Clignez les yeux une fois pour oui, deux fois pour non ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5860, 165, 'kmr', 'Ji bo ku tu bêje erê careke,ji bo ku tu bêje na du caran çave xwe bigire');
INSERT INTO term (id, entry_id, lang, text) VALUES (5861, 165, 'zza', 'eke wana hiya ju rae çima ho kırpmıs ke, eke wana nie çime ho dire kırkmıs ke');
INSERT INTO term (id, entry_id, lang, text) VALUES (5862, 165, 'ar', 'ارمش مرة للنعم ومرتين للرفض');
INSERT INTO term (id, entry_id, lang, text) VALUES (5863, 165, 'el', 'Ανοιγοκλείστε τα μάτια μια φορά για Ναι δύο φορές για Όχι');
INSERT INTO term (id, entry_id, lang, text) VALUES (5864, 165, 'ja', '「はい」なら瞬き1回、「いいえ」なら瞬きを2回してください。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5865, 165, 'he', 'למצמץ פעם אחת ל"כן" ופעמיים ל"לא"');
INSERT INTO term (id, entry_id, lang, text) VALUES (5866, 165, 'it', 'Chiudi le palpebre una volta per dire sì e due volte per no');
INSERT INTO term (id, entry_id, lang, text) VALUES (5867, 165, 'hy', '«Այո» ասելու համար թարթիր մեկ, «ոչ» ասելու համար՝ երկու անգամ։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5868, 165, 'nl', 'Eén keer knipperen betekent ''ja''. Twee keer knipperen betekent ''nee''. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5869, 165, 'zh-Hans', '眨眼一次表示 "是"，两次表示 "否"。');
INSERT INTO term (id, entry_id, lang, text) VALUES (5870, 165, 'zh-Hant', '眨眼一次表示「是」，兩次表示「否」');
INSERT INTO term (id, entry_id, lang, text) VALUES (5871, 165, 'bg', 'За "да" мигни веднъж, за "не" два пъти.');
INSERT INTO term (id, entry_id, lang, text) VALUES (5872, 165, 'ko', '네''면 눈을 한 번, ''아니오''면 두 번 깜빡이세요 ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5873, 165, 'fa', 'برای بله یک بار و برای خیر دو بار پلک بزن');
INSERT INTO term (id, entry_id, lang, text) VALUES (5874, 165, 'hi', 'हाँ के लिए एक बार और न के लिए दो बार पलकें झपकाएँ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5875, 165, 'pt', 'Pisque uma vez para sim e duas vezes para não');
INSERT INTO term (id, entry_id, lang, text) VALUES (5876, 165, 'sv', 'Blinka en gång för ja och två gånger för nej');
INSERT INTO term (id, entry_id, lang, text) VALUES (5877, 165, 'ro', 'Clipește o dată pentru da și de două ori pentru nu');
INSERT INTO term (id, entry_id, lang, text) VALUES (5878, 165, 'mk', 'Трепни еднаш за „да“ и два пати за „не“');
INSERT INTO term (id, entry_id, lang, text) VALUES (5879, 165, 'hu', 'Pislogjon egyet, ha igen, kettőt, ha nem!');
INSERT INTO term (id, entry_id, lang, text) VALUES (5880, 165, 'pl', 'Mrugnij raz na tak i twa razy na nie');
INSERT INTO term (id, entry_id, lang, text) VALUES (5881, 166, 'de', 'Kannst Du mich hören?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5882, 166, 'ru', 'Вы слышите меня?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5883, 166, 'fr', 'Vous pouvez m''entendre ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5884, 166, 'kmr', 'Tu min dibihîsî?/Dengê min tê te?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5885, 166, 'zza', 'mı hesnena');
INSERT INTO term (id, entry_id, lang, text) VALUES (5886, 166, 'ar', 'هل تسمعني ؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5887, 166, 'el', 'Μπορείς να με ακούσεις;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5888, 166, 'ja', '私の声は聞こえますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5889, 166, 'he', 'האם את/ה שומע/ת אותי?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5890, 166, 'it', 'Mi senti?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5891, 166, 'hy', 'Լսո՞ւմ ես ինձ։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5892, 166, 'nl', 'Kan u mij horen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5893, 166, 'zh-Hans', '你能听到我妈？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5894, 166, 'zh-Hant', '您聽得到我的聲音嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5895, 166, 'bg', 'Чуваш ли ме?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5896, 166, 'ko', '제 목소리 들리세요? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5897, 166, 'fa', ' آیا صدای من را میشنوی؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5898, 166, 'hi', 'क्या आप मुझे सुन सकते हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5899, 166, 'pt', 'Consegue ouvir-me?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5900, 166, 'sv', 'Kan du höra mig?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5901, 166, 'ro', 'Mă poți auzi?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5902, 166, 'mk', 'Ме слушаш ли? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5903, 166, 'hu', 'Hall engem?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5904, 166, 'fi', 'Kuuletko minut?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5905, 166, 'pl', 'Słyszysz mnie?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5906, 167, 'de', 'Kannst du mich sehen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5907, 167, 'ru', 'Вы видите меня?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5908, 167, 'fr', 'Vous pouvez me voir ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5909, 167, 'kmr', 'Tu min dibinî?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5910, 167, 'zza', 'mı venena');
INSERT INTO term (id, entry_id, lang, text) VALUES (5911, 167, 'ar', 'هل يمكنك رؤيتي؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5912, 167, 'el', 'Μπορείς να με δεις;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5913, 167, 'ja', '私が見えますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5914, 167, 'he', 'האם את/ה רואה אותי?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5915, 167, 'it', 'Mi vedi?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5916, 167, 'hy', 'Տեսնո՞ւմ ես ինձ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5917, 167, 'nl', 'Kan u mij zien?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5918, 167, 'zh-Hans', '你会看见我吗？ // 你看清我妈？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5919, 167, 'zh-Hant', '您看得到我嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5920, 167, 'bg', 'Виждаш ли ме?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5921, 167, 'ko', '제가 보이세요? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5922, 167, 'fa', ' آیا من را میتوانی ببینی؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5923, 167, 'hi', 'क्या आप मुझे देख सकते हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5924, 167, 'pt', 'Consegue ver-me?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5925, 167, 'sv', 'Kan du se mig?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5926, 167, 'ro', 'Mă poți vedea?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5927, 167, 'mk', 'Ме гледаш ли?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5928, 167, 'hu', 'Lát engem?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5929, 167, 'fi', 'Näetkö minut?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5930, 167, 'pl', 'Widzisz mnie?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5931, 168, 'de', 'Kannst Du deine .... bewegen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5932, 168, 'ru', 'Вы можете пошевелить ...?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5933, 168, 'fr', 'Vous pouvez bouger votre/vos ...?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5934, 168, 'kmr', 'Tu dikarî .... bi lebitinî/tev bigerênî?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5935, 168, 'zza', 'Tı eşkena ….. xo bıleqin');
INSERT INTO term (id, entry_id, lang, text) VALUES (5936, 168, 'ar', 'هل تستطيع تحريك (عضو الجسم)؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5937, 168, 'el', 'Μπορείτε να κουνήσετε το (μέρος του σώματός σας εδώ);');
INSERT INTO term (id, entry_id, lang, text) VALUES (5938, 168, 'ja', '（体の部位）は動かせますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5939, 168, 'he', 'האם את/ה יכול/ה להזיז את ה[שם האיבר]?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5940, 168, 'it', 'Riesci a muovere (parte del corpo)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5941, 168, 'hy', 'Կարո՞ղ ես շարժել (մարմնի այս մասը):');
INSERT INTO term (id, entry_id, lang, text) VALUES (5942, 168, 'nl', 'Kan u uw ... bewegen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5943, 168, 'zh-Hans', '你的...能动吗？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5944, 168, 'zh-Hant', '您的…能動嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5945, 168, 'bg', 'Можеш ли да си раздвижиш ... ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5946, 168, 'ko', '이 부위를 움직일 수 있습니까?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5947, 168, 'fa', 'آیا (قسمت بدن) را میتوانی تکان بدهی؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5948, 168, 'hi', 'क्या आप (शरीर का अंग) हिला सकते हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5949, 168, 'pt', 'Consegue mexer (parte do corpo)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5950, 168, 'sv', 'Kan du röra på …?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5951, 168, 'ro', 'Îți poți mișca ... ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5952, 168, 'mk', 'Може ли да го/ја мрднеш (дел од телото)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5953, 168, 'hu', 'Tudja mozgatni a...?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5954, 168, 'fi', 'Voitko liikuttaa....?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5955, 168, 'pl', 'Możesz ruszać...?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5956, 169, 'de', 'Hast Du Atemnot?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5957, 169, 'ru', 'Вам трудно дышать? / Вы дышите легко?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5958, 169, 'fr', 'Avez-vous des difficultés à respirer ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5959, 169, 'kmr', 'Hilkişandina nefesê/bêhne ji bo te zehmete?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5960, 169, 'zza', 'Tı eşkena nefes bıgeri?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5961, 169, 'ar', 'هل تعاني من صعوبة في التنفس؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5962, 169, 'el', 'Δυσκολεύεσαι να αναπνεύσεις;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5963, 169, 'ja', '息がしづらくはありませんか？/楽に呼吸できていますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5964, 169, 'he', 'קשה לך לנשום?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5965, 169, 'it', 'Fai fatica a respirare? / Hai difficoltà respiratorie?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5966, 169, 'hy', 'Դժվարանում ե՞ս շնչել։ Հե՞շտ ես շնչում։');
INSERT INTO term (id, entry_id, lang, text) VALUES (5967, 169, 'nl', 'Is het lastig om te ademen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5968, 169, 'zh-Hans', '你有呼吸困难吗？ // 你是否有呼吸困难？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5969, 169, 'zh-Hant', '您有呼吸困難嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5970, 169, 'bg', 'Затрудняваш ли се с дишането? / Можеш ли да си взимаш въздох?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5971, 169, 'ko', '호흡이 힘드십니까? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5972, 169, 'fa', ' آیا میتوانی راحت نفس بکشی؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5973, 169, 'hi', 'क्या आपको साँस लेने में दिक्कत है?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5974, 169, 'pt', 'Tem dificuldade em respirar?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5975, 169, 'sv', 'Har du svårt att andas?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5976, 169, 'ro', 'Ai probleme cu respirația? Poți respira ușor?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5977, 169, 'mk', 'Дали тешко дишеш?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5978, 169, 'hu', 'Nehezen lélegzik?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5979, 169, 'fi', 'Onko sinun vaikea hengittää?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5980, 170, 'de', 'Kannst Du deine Finger / Zehen an deinem/deiner rechten/linken Hand/Fuss bewegen? ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5981, 170, 'ru', 'Можете ли вы шевелить пальцами правой/левой руки/ноги?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5982, 170, 'fr', 'Pouvez-vous bouger vos doigts et orteils droits et gauches ?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5983, 170, 'kmr', 'Tu dikarî tilikên xwe yen ling/pê-destan bi lebitene?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5984, 170, 'zza', 'Tı eşkena desti/lınge xo het çep/raşt bıleqin?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5985, 170, 'ar', 'هل يمكنك تحريك أصابع يدك/قدمك اليمنى/اليسرى؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (5986, 170, 'el', 'Μπορείτε να κουνήσετε τα δάχτυλα του δεξιού/αριστερού σας χεριού/πόδι;');
INSERT INTO term (id, entry_id, lang, text) VALUES (5987, 170, 'ja', '右手／左手／右足／左足の指は動かせますか？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5988, 170, 'he', 'האם את/ה יכול/ה להזיז את האצבעות ביד / ברגל הימנית / השמאלית שלך?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5989, 170, 'it', 'Riesci a muovere le dita della mano/del piede destra-o/sinistra-o');
INSERT INTO term (id, entry_id, lang, text) VALUES (5990, 170, 'hy', 'Կարո՞ղ ես շարժել աջ/ձախ ձեռքի/ոտքի մատները:');
INSERT INTO term (id, entry_id, lang, text) VALUES (5991, 170, 'nl', 'Kan u de vingers / tenen van uw rechter- / linker- hand/voet bewegen?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5992, 170, 'zh-Hans', '你能移动你友/左手/脚的手/脚字吗?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5993, 170, 'zh-Hant', '您能移動您的[右/左][手/脚]的指頭嗎？');
INSERT INTO term (id, entry_id, lang, text) VALUES (5994, 170, 'bg', 'Можеш ли да си раздвижваш дясната/лявата ръка или десният/левият крак?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5995, 170, 'ko', '오른쪽/왼쪽 손/발 움직일 수 있으세요?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5996, 170, 'fa', '  انگشت های دست و پای چپ و راستت را میتوانی تکان بدهی؟ ');
INSERT INTO term (id, entry_id, lang, text) VALUES (5997, 170, 'hi', 'क्या आप अपने दाएँ/बाएँ हाथ/पैर की उंगलियों को हिला सकते हैं?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5998, 170, 'pt', 'Consegue mexer os dedos da mão/do pé direita(o)/esquerda(o)?');
INSERT INTO term (id, entry_id, lang, text) VALUES (5999, 170, 'sv', 'Kan du röra på fingrarna/tårna på höger/vänster hand/fot?');
INSERT INTO term (id, entry_id, lang, text) VALUES (6000, 170, 'ro', 'Poți mișca degetele mâinii/piciorului drept/stâng?');
INSERT INTO term (id, entry_id, lang, text) VALUES (6001, 170, 'mk', 'Можеш ли да мрднеш со прстите на десната/левата рака/нога?');
