INSERT INTO term (id, entry_id, lang, text) VALUES (10308, 368, 'kmr', 'Ne raze./Qet ne raze.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10309, 368, 'zza', 'Qeta hewna meşo');
INSERT INTO term (id, entry_id, lang, text) VALUES (10310, 368, 'ar', 'لا تنم');
INSERT INTO term (id, entry_id, lang, text) VALUES (10311, 368, 'el', 'Μην πάτε να κοιμηθείτε');
INSERT INTO term (id, entry_id, lang, text) VALUES (10312, 368, 'ja', '絶対に眠ってはいけません');
INSERT INTO term (id, entry_id, lang, text) VALUES (10313, 368, 'he', 'לא ללכת לישון.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10314, 368, 'it', 'Non ti addormentare / resta sveglio');
INSERT INTO term (id, entry_id, lang, text) VALUES (10315, 368, 'hy', 'Հանկարծ չքնես։');
INSERT INTO term (id, entry_id, lang, text) VALUES (10316, 368, 'nl', 'Val niet in slaap. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (10317, 368, 'zh-Hans', '别睡觉!');
INSERT INTO term (id, entry_id, lang, text) VALUES (10318, 368, 'zh-Hant', '不要睡著');
INSERT INTO term (id, entry_id, lang, text) VALUES (10319, 368, 'ko', '잠들지 마세요.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10320, 368, 'fa', 'نخواب');
INSERT INTO term (id, entry_id, lang, text) VALUES (10321, 368, 'hi', 'सोना मत।');
INSERT INTO term (id, entry_id, lang, text) VALUES (10322, 368, 'sv', 'Somna inte.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10323, 368, 'ro', 'Nu adormi.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10324, 368, 'mk', 'Не заспивај.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10325, 368, 'hu', 'Ne aludjon el.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10326, 368, 'fi', 'Älä nuku.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10327, 368, 'pl', 'Nie zasypiaj/ Nie idź spać');
INSERT INTO term (id, entry_id, lang, text) VALUES (10328, 369, 'de', 'Halten Sie durch!');
INSERT INTO term (id, entry_id, lang, text) VALUES (10329, 369, 'ru', 'Осталось чуть-чуть, потерпи ещё немного. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (10330, 369, 'fr', 'On y est presque, tenez bon.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10331, 369, 'kmr', 'Hindik ma,hinekî din jî bisekine-xwe bigre.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10332, 369, 'zza', 'Tay menda, deymiş bıbo');
INSERT INTO term (id, entry_id, lang, text) VALUES (10333, 369, 'ar', 'لقد وصلنا ، أصمد قليلا');
INSERT INTO term (id, entry_id, lang, text) VALUES (10334, 369, 'el', 'Σχεδόν τα καταφέραμε, κρατηθείτε/κρατήσου για λίγο ακόμη');
INSERT INTO term (id, entry_id, lang, text) VALUES (10335, 369, 'ja', 'もうあと少しです。もう少し頑張って。');
INSERT INTO term (id, entry_id, lang, text) VALUES (10336, 369, 'he', 'כמעט הגענו, החזק/החזיקי מעמד עוד קצת.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10337, 369, 'it', 'Manca poco, resisti');
INSERT INTO term (id, entry_id, lang, text) VALUES (10338, 369, 'hy', 'Քիչ մնաց, մի քիչ էլ դիմացիր։');
INSERT INTO term (id, entry_id, lang, text) VALUES (10339, 369, 'zh-Hans', '等一会儿、很快/马上就要结束、请你保住一下。');
INSERT INTO term (id, entry_id, lang, text) VALUES (10340, 369, 'zh-Hant', '我們快到了，請再撐一下');
INSERT INTO term (id, entry_id, lang, text) VALUES (10341, 369, 'ko', '조금만 더 버텨봐요.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10342, 369, 'fa', 'کم مانده یک کم بیشتر صبر کن.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10343, 369, 'hi', 'बस हो गया, थोड़ा सा और रुकिए।');
INSERT INTO term (id, entry_id, lang, text) VALUES (10344, 369, 'sv', 'Vi är snart framme, håll ut lite till.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10345, 369, 'ro', 'Aproape am ajuns, mai rezistă puțin.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10346, 369, 'mk', 'Речиси е готово, издржи уште малку.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10347, 369, 'hu', 'Mindjárt meglesz, csak egy kicsit tartson ki.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10348, 370, 'de', 'Wir holen sie da raus!');
INSERT INTO term (id, entry_id, lang, text) VALUES (10349, 370, 'ru', 'Мы тебя достанем оттуда. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (10350, 370, 'fr', 'On va vous sortir de là. ');
INSERT INTO term (id, entry_id, lang, text) VALUES (10351, 370, 'kmr', 'Emê te ji wir derxin');
INSERT INTO term (id, entry_id, lang, text) VALUES (10352, 370, 'zza', 'Ma tı o cara vejeni');
INSERT INTO term (id, entry_id, lang, text) VALUES (10353, 370, 'ar', 'سوف نخرجك من هنا');
INSERT INTO term (id, entry_id, lang, text) VALUES (10354, 370, 'el', 'Θα σε/σας βγάλουμε από εδώ');
INSERT INTO term (id, entry_id, lang, text) VALUES (10355, 370, 'ja', 'そこから出してあげます');
INSERT INTO term (id, entry_id, lang, text) VALUES (10356, 370, 'he', 'אנחנו נוציא אותך מכאן.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10357, 370, 'it', 'Ti tireremo fuori di qui');
INSERT INTO term (id, entry_id, lang, text) VALUES (10358, 370, 'hy', 'Քեզ դուրս ենք բերելու այդտեղից։');
INSERT INTO term (id, entry_id, lang, text) VALUES (10359, 370, 'zh-Hans', '我们会带您出来。');
INSERT INTO term (id, entry_id, lang, text) VALUES (10360, 370, 'zh-Hant', '我們會帶您離開這裡');
INSERT INTO term (id, entry_id, lang, text) VALUES (10361, 370, 'ko', '우리가 당신을 거기서 데려올게요.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10362, 370, 'fa', 'شما را از آنجا بیرون می‌آوریم.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10363, 370, 'hi', 'हम आपको वहां से निकाल लेंगे।');
INSERT INTO term (id, entry_id, lang, text) VALUES (10364, 370, 'sv', 'Vi ska få ut dig därifrån.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10365, 370, 'ro', 'O să te scoatem de acolo.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10366, 370, 'mk', 'Ќе те извлечеме оттаму.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10367, 370, 'hu', 'Kihozzuk onnan.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10368, 370, 'fi', 'Pelastamme sinut sieltä.');
INSERT INTO term (id, entry_id, lang, text) VALUES (10369, 370, 'pl', 'Wydostaniemy cię z tąd');
INSERT INTO term (id, entry_id, lang, text) VALUES (10370, 371, 'de', 'Wie heisst Du!');
INSERT INTO term (id, entry_id, lang, text) VALUES (10371, 371, 'ru', 'Как вас зовут? / Как тебя зовут?');
