INSERT INTO term (id, entry_id, lang, text) VALUES (10373, 371, 'kmr', 'Navê we çi ye?/Navê te çi ye?/Navê we-te bi xêr?');
INSERT INTO term (id, entry_id, lang, text) VALUES (10374, 371, 'zza', 'Name to çiyo?');
INSERT INTO term (id, entry_id, lang, text) VALUES (10375, 371, 'ar', 'ما اسمك ؟');
INSERT INTO term (id, entry_id, lang, text) VALUES (10376, 371, 'el', 'Πώς σε λένε; / Πώς σας λένε;');
